function cityBuildWallDef.getJiantaOffset(wallModel, dir)
	local tb = cityBuildWallDef.chengjiantaDef[tostring(wallModel)]
	if SoraDGetFactionType() == FACTION_TYPE.FACTION_BYZANTINE then
		tb = cityBuildWallDef.chengjiantaBztDef[tostring(wallModel)]
	end
	cityBuildWallDef = cityBuildWallDef.chengjiantaBztDef
	cityBuildWallDef.chengjiantaBztDef.x = 0
	local cityBuildWallDef.chengjiantaBztDef.y, offset = 0, cityBuildWallDef.chengjiantaBztDef
	if tb and tb[dir] then
		cityBuildWallDef = tb[dir]
		tb[dir].x = tb[dir].x
		offset, tb[dir].y = tb[dir], tb[dir].y
	end
	return offset
end
function cityBuildWallDef.getJiantaBasePos(wallModel, dir)
	local pos = cc.p(0, 0)
	local tb = cityBuildWallDef.chengjiantabaseDef[tostring(wallModel)]
	if tb and tb[dir] then
		pos = tb[dir]
	end
	return pos
end
function cityBuildWallDef.getChengqiangPos(wallModel, index)
	return cityBuildWallDef.chengqiangDef[tostring(wallModel)][index]
end
function cityBuildWallDef.getChengqiangLight(wallModel)
	local config = cityBuildWallDef.chengqiangLightDef[tostring(wallModel)]
	if SoraDGetFactionType() == FACTION_TYPE.FACTION_BYZANTINE then
		config = cityBuildWallDef.chengqiangLightBTZDef[tostring(wallModel)]
	end
	local node = display.newNode()
	if config then
		for k, v in pairs(config) do
			if v.pos then
				local light = display.newSprite("#" .. v.png)
				light:setPosition(v.pos.x, v.pos.y)
				if SoraDGetFactionType() == FACTION_TYPE.FACTION_BYZANTINE then
					light:setPosition(v.pos.x, v.pos.y)
				end
				cityBuildWallDef = v.pos.x
				v.pos.x.beginOpacity = 0.6
				v.pos.x.endOpacity = 1
				SoraDFadeINOUT(light, v.pos.x)
				light:addTo(node)
			end
			if v.posArray then
				for i, pos in ipairs(v.posArray) do
					local light = display.newSprite("#" .. v.png)
					light:setPosition(pos.x, pos.y)
					if SoraDGetFactionType() == FACTION_TYPE.FACTION_BYZANTINE then
						light:setPosition(pos.x, pos.y)
					end
					cityBuildWallDef = pos.x
					pos.x.beginOpacity = 0.6
					pos.x.endOpacity = 1
					SoraDFadeINOUT(light, pos.x)
					light:addTo(node)
				end
			end
		end
	end
	return node
end
return cityBuildWallDef
